"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82960"],{14901(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.regra_cita_fato_posterior_a_inscricao","status":422,"titulo":"A regra da modalidade cita fato que s\xf3 \xe9 conhecido depois da inscri\xe7\xe3o"},"descricao":{"codigo":"uniplus.configuracao.modalidade.regra_cita_fato_posterior_a_inscricao","requisitos":[],"oQueAconteceu":["H\xe1 uma recusa por condi\xe7\xe3o, no campo `regraDeAplicabilidade[c][i].fato`, com cl\xe1usula e condi\xe7\xe3o contadas a partir de zero.","Alguma condi\xe7\xe3o de `regraDeAplicabilidade` cita um fato que o Uni+ n\xe3o consegue afirmar que j\xe1 \xe9 conhecido **na inscri\xe7\xe3o**. A regra de aplicabilidade decide a quais modalidades o candidato concorre no momento em que ele se inscreve, e s\xf3 aceita fato cujo ponto de resolu\xe7\xe3o \xe9 a pr\xf3pria inscri\xe7\xe3o ou uma fase que a precede. A recusa fecha por padr\xe3o e vale em dois casos:","- o fato \xe9 resolvido numa fase posterior \xe0 inscri\xe7\xe3o, como o resultado final;\\n- n\xe3o h\xe1 preced\xeancia declarada, entre as fases, que comprove que o ponto de resolu\xe7\xe3o do fato vem antes da inscri\xe7\xe3o: a fase sem essa preced\xeancia n\xe3o conta como anterior.","Nada foi gravado.","Na atualiza\xe7\xe3o, a modalidade \xe9 procurada antes desta confer\xeancia: com um identificador inexistente a resposta \xe9 [modalidade n\xe3o encontrada](/erros/uniplus.configuracao.modalidade.nao_encontrada), mesmo que o conte\xfado enviado tamb\xe9m tivesse este problema. Numa modalidade do cat\xe1logo legal fixo esta recusa n\xe3o \xe9 emitida: se o conte\xfado altera algo al\xe9m da descri\xe7\xe3o e da base legal, vale [estrutura protegida n\xe3o edit\xe1vel](/erros/uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel)."],"comoResolver":["Troque a condi\xe7\xe3o por um fato conhecido na inscri\xe7\xe3o, ou retire-a da regra. Se o fato deveria ser conhecido na inscri\xe7\xe3o, confira o ponto de resolu\xe7\xe3o do fato e as preced\xeancias entre as fases, que dizem quais fases v\xeam antes da inscri\xe7\xe3o."],"ondeAparece":["Cria\xe7\xe3o de uma modalidade (POST /api/configuracao/admin/modalidades)","Atualiza\xe7\xe3o de uma modalidade fora do cat\xe1logo legal fixo (PUT /api/configuracao/admin/modalidades/`{id}`), depois de a modalidade ser encontrada"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);